const item = $input.item.json;

const targetPhrases = String(item.target_phrases || '')
  .split(',')
  .map(s => s.trim())
  .filter(Boolean);

const searchKeywords = String(item.search_keywords || '')
  .split(',')
  .map(s => s.trim())
  .filter(Boolean);

const brief = {
  trend_id: item.id,
  date: item.date,
  episode_title: item.episode_title,
  workplace_angle: item.workplace_angle,
  emotional_hook: item.emotional_hook,
  target_phrases: targetPhrases,
  raw_trend: item.raw_trend,
  source: item.source,
  priority: item.priority,
  search_keywords: searchKeywords,
  status: item.status || 'pending'
};

return {
  json: {
    episode_brief: brief
  }
};

// 输入是你贴的那种结构：[{ output: "{...json string...}" }]

// 1. 拿到唯一一条 item
const raw = $input.first().json.output.trending_workplace_topics;

// 2. 把 output 里的字符串 JSON 解析出来
const parsed = raw;

// 现在 parsed 的结构就是：{ date: "...", trending_workplace_topics: [ {...}, {...} ] }
const topics = parsed|| [];
const date = $input.first().json.output.date || new Date().toISOString().slice(0, 10);

// 3. 为 Pinecone 准备 text + metadata
return topics.map(t => {
  const text = `
Trend: ${t.original_trend}
Workplace angle: ${t.workplace_scenario}
Episode idea: ${t.episode_title}
Emotional hook: ${t.emotional_hook}
Target phrases: ${Array.isArray(t.target_phrases) ? t.target_phrases.join(', ') : ''}
`.trim();

  return {
    json: {
      id: `${date}-${t.original_trend}`.replace(/\s+/g, '_').slice(0, 80),
      text,
      metadata: {
        source: t.source,
        date,
        priority: t.priority,
        episode_title: t.episode_title,
        raw_trend: t.original_trend,
        search_keywords: t.search_keywords
      }
    }
  };
});

const items = $input.all();

const usedTopics = new Set();
const usedTitles = new Set();
const usedHeroPhrases = new Set();

let lastRow = 0;

for (const item of items) {
  const j = item.json;

  // collect used fields
  if (j.Topic) usedTopics.add(String(j.Topic).trim());
  if (j.Title) usedTitles.add(String(j.Title).trim());
  if (j.Hero_Phrase) usedHeroPhrases.add(String(j.Hero_Phrase).trim());

  // track last row_number from Google Sheets node
  const rowNum = j.Row;
  if (typeof rowNum === 'number' && rowNum > lastRow) {
    lastRow = rowNum;
  }
}

// if sheet might be empty and row_number is missing, lastRow will stay 0
return [{
  json: {
    last_row: lastRow,
    used_topics: Array.from(usedTopics),
    used_titles: Array.from(usedTitles),
    used_hero_phrases: Array.from(usedHeroPhrases),
trend_themes:$('data_beautify').all()

  }
}];

const data = $input.first().json;

// ---- 1) Parse Gemini output ----
const textContent = data.content?.parts?.[0]?.text;
if (!textContent) {
  return [{ json: { error: "No text content from Gemini" } }];
}

let parsed;
try {
  parsed = JSON.parse(textContent);
} catch (e) {
  return [{ json: { error: "Failed to parse JSON: " + e.message, raw: textContent } }];
}
if (!Array.isArray(parsed)) parsed = [parsed];

// ---- 2) Build episode_id from Sheets row ----
const sheetRow = $('Get row(s) in sheet').first().json.Row;
const episodeId = `ep_${String(sheetRow).padStart(3, '0')}`;

// ---- 3) Speaker mapping ----
const DEFAULT_SPEAKER_MAPPING = {
  Jordan: "Achird",
  Riley: "Kore",
  Tom: "Charon",
  Anna: "Aoede",
  Speaker1: "Achird",
  Speaker2: "Kore",
  Speaker3: "Charon",
  Speaker4: "Aoede",
};

function generateSpeakerConfigs(turns) {
  const unique = new Set();
  (turns || []).forEach(t => t?.speaker && unique.add(t.speaker));
  return Array.from(unique).map(alias => ({
    speakerAlias: alias,
    speakerId: DEFAULT_SPEAKER_MAPPING[alias] || "Kore",
  }));
}

// ---- 4) Convert each section -> ONE item payload for VPS /generate ----
const channel = "hero_english";

const items = parsed.map((section, idx) => {
  // Extract name and remove square brackets
  let name = section.section || section.name || "SECTION";
  name = name.replace(/^\[|\]$/g, '').trim();

  // Prefer Gemini-provided index if exists; otherwise assign sequential
  const index = Number.isFinite(section.index) ? Number(section.index) : (idx + 1);

  const prompt = section.prompt || "";

  const turns = Array.isArray(section.turns) ? section.turns : [];
  const hasTurns = turns.length > 0;

  let oneSection;

  if (hasTurns) {
    // MULTI
    let speakerConfigs = Array.isArray(section.speaker_configs) ? section.speaker_configs : [];
    if (speakerConfigs.length === 0) {
      speakerConfigs = generateSpeakerConfigs(turns);
    }

    oneSection = {
      name,
      index,
      episode_id: episodeId,
      prompt,
      turns,
      speaker_configs: speakerConfigs,
      type: "multi",
    };
  } else {
    // SINGLE
    const text = section.text || "";
    if (!text) {
      oneSection = {
        name,
        index,
        episode_id: episodeId,
        error: "Section has neither turns nor text",
        raw: section,
      };
    } else {
      oneSection = {
        name,
        index,
        episode_id: episodeId,
        prompt,
        text,
        type: "single",
      };
    }
  }

  return {
    json: {
      channel,
      episode_id: episodeId,
      sections: [oneSection],
    }
  };
});

return items;

// Loop over input items and add a new field called 'myNewField' to the JSON of each one
for (const item of $input.all()) {
  item.json.myNewField = 1;
}

return JSON.parse($input.first().json.content.parts[0].text);

